Notes:

```cpp
    completed_split_operation_filter_ = MakeFunctorOperationFilter(
        [this](const OpId& op_id, consensus::OperationType op_type) -> Status {
          if (SplitOperation::ShouldAllowOpAfterSplitTablet(op_type)) {
            return Status::OK();
          }

          auto children = metadata_->split_child_tablet_ids();
          return SplitOperation::RejectionStatus(OpId(), op_id, op_type, children[0], children[1]);
        });
```

1. rpc -> parent tablet : get TABLET_SPLIT error
2. Non-retryable internally in the current rpc call by DoDelayedRetry
3. Restart session and route to the child tablet instead (YQL_STATUS_RESTART_REQUIRED_ERROR)

```cpp
TabletInvoker::Done {
   …
  const bool is_tablet_split = ErrorCode(rsp_err) == tserver::TabletServerErrorPB::TABLET_SPLIT;
  if (is_tablet_split || ClientError(*status) == ClientErrorCode::kTablePartitionListIsStale) {
    // Replace status error with TryAgain, so upper layer retry request after refreshing
    // table partitioning metadata.
    *status = status->CloneAndReplaceCode(Status::kTryAgain);
    if (is_tablet_split) {
      tablet_->MarkAsSplit();
    }
    rpc_->Failed(*status);
    return true;
  }
  …
}

 ```
=>
```cpp
AsyncRpc::Failed{
      ...
      case YBOperation::Type::QL_READ: FALLTHROUGH_INTENDED;
      case YBOperation::Type::QL_WRITE: {
        QLResponsePB* resp = down_cast<YBqlOp*>(yb_op)->mutable_response();
        resp->Clear();
        resp->set_status(status.IsTryAgain() ? QLResponsePB::YQL_STATUS_RESTART_REQUIRED_ERROR
                                             : QLResponsePB::YQL_STATUS_RUNTIME_ERROR);
        resp->set_error_message(error_message);
        break;
      }
      ...
}
```

This will have a brand new rpc call instance for the child tablet, hence new request_id.
